        private static readonly IReadOnlyList<CoreBattleCard> expanded = BuildExpanded();
        private static IReadOnlyList<CoreBattleCard> BuildExpanded()
        {
            var result = new List<CoreBattleCard>(all);
            result.AddRange(CoreNavalSchoolExpansionCatalog.All);
            return result.AsReadOnly();
        }
        public static IReadOnlyList<CoreBattleCard> All => expanded;
        public static CoreBattleCard ForSource(string sourceId)
        {
            if (string.IsNullOrEmpty(sourceId)) return null;
            foreach (CoreBattleCard card in all)
                if (card.RequiredCrew == sourceId || card.RequiredComponent == sourceId) return card;
            return null;
        }
        public static CoreBattleCard Find(string id)
        {
            foreach (CoreBattleCard card in All) if (card.Id == id) return card;
            return null;
        }
        public static int RequiredPirateLevel(string schoolId)
        {
            switch(schoolId){case "fire":return 2;case "arcane":return 3;case "curse":return 4;case "tide":return 5;case "thunder":return 7;case "blood":return 10;default:return 1;}
        }
    }
